package tersenet

// The SDK against vectors/entries.txt (each invalid entry refused for
// the rule sdk/testdata/reasons.txt names), the strictness cases of
// sdk/testdata/strict.txt (generated by the Rust SDK's tests), what the
// standard library's ed25519.Verify accepts, and arbitrary bytes.

import (
	"bufio"
	"crypto/ed25519"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"strconv"
	"strings"
	"testing"
)

type record struct {
	head   string
	fields map[string]string
}

func records(t testing.TB, path string) []record {
	text, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var out []record
	for _, block := range strings.Split(string(text), "\n\n") {
		var r *record
		for _, line := range strings.Split(block, "\n") {
			switch {
			case line == "" || strings.HasPrefix(line, "#"):
			case r == nil:
				r = &record{head: line, fields: map[string]string{}}
			case strings.HasPrefix(line, "  "):
				k, v, _ := strings.Cut(line[2:], " ")
				r.fields[k] = v
			}
		}
		if r != nil {
			out = append(out, *r)
		}
	}
	return out
}

func unhex(t testing.TB, s string) []byte {
	if s == "-" {
		return nil
	}
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

var rules = map[string]error{
	"Length": ErrLength, "TitleLength": ErrTitleLength, "TitleUtf8": ErrTitleUTF8,
	"Seq": ErrSeq, "Kind": ErrKind, "Size": ErrSize, "Name": ErrName, "Key": ErrKey,
	"SignatureS": ErrSignatureS, "SignatureR": ErrSignatureR, "Signature": ErrSignature,
}

func TestEntryVectors(t *testing.T) {
	reasons := map[string]string{}
	f, err := os.Open("../testdata/reasons.txt")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	for s := bufio.NewScanner(f); s.Scan(); {
		if name, rule, ok := strings.Cut(s.Text(), " "); ok && !strings.HasPrefix(name, "#") {
			reasons[name] = rule
		}
	}
	valid, invalid := 0, 0
	for _, r := range records(t, "../../vectors/entries.txt") {
		name, ok := strings.CutPrefix(r.head, "entry ")
		if !ok {
			continue
		}
		e, err := VerifyEntry(unhex(t, r.fields["bytes"]))
		if r.fields["valid"] == "yes" {
			if err != nil {
				t.Fatalf("%s: refused: %v", name, err)
			}
			title, _ := strconv.Unquote(r.fields["title"])
			got := fmt.Sprintf("%x %d %d %d %d %x %x %q", e.Feed, e.Seq, e.Time, e.Kind, e.Size, e.Blob, e.ReplyTo, e.Title)
			want := fmt.Sprintf("%s %s %s %s %s %s %s %q", r.fields["feed-key"], r.fields["seq"], r.fields["time"],
				r.fields["kind"], r.fields["size"], r.fields["blob-id"], r.fields["reply-to"], title)
			if got != want {
				t.Errorf("%s:\n got %s\nwant %s", name, got, want)
			}
			valid++
			continue
		}
		want, ok := rules[reasons[name]]
		if !ok {
			t.Fatalf("%s: no reason in reasons.txt", name)
		}
		if !errors.Is(err, want) {
			t.Errorf("%s: got %v, want %v", name, err, want)
		}
		invalid++
	}
	if valid < 10 || invalid != len(reasons) {
		t.Fatalf("%d valid, %d invalid, %d reasons", valid, invalid, len(reasons))
	}
}

func TestStrictnessCases(t *testing.T) {
	cases := records(t, "../testdata/strict.txt")
	accepted := 0
	for _, c := range cases {
		name := strings.TrimPrefix(c.head, "case ")
		key, msg, sig := unhex(t, c.fields["key"]), unhex(t, c.fields["message"]), unhex(t, c.fields["signature"])
		expect := c.fields["expect"]
		if Verify(key, msg, sig) != (expect == "valid") {
			t.Errorf("%s: Verify gives %v, want %s", name, !(expect == "valid"), expect)
		}
		err := verify(key, msg, sig)
		if expect != "valid" && !errors.Is(err, rules[expect]) {
			t.Errorf("%s: %v, want %s", name, err, expect)
		}
		if expect == "Key" && ValidFeedKey(key) {
			t.Errorf("%s: a valid feed key", name)
		}
		if expect == "valid" {
			accepted++
		}
	}
	if len(cases) < 50 || accepted != 8 {
		t.Fatalf("%d cases, %d valid", len(cases), accepted)
	}
}

// The claims the reference article makes about crypto/ed25519.Verify:
// it accepts small-order keys (also written non-canonically) and a
// small-order R, and refuses S >= L and a mixed-order R.
func TestWhatTheStandardLibraryDoes(t *testing.T) {
	byName := map[string]record{}
	for _, c := range records(t, "../testdata/strict.txt") {
		byName[strings.TrimPrefix(c.head, "case ")] = c
	}
	std := func(name string) bool {
		c := byName[name]
		return ed25519.Verify(unhex(t, c.fields["key"]), unhex(t, c.fields["message"]), unhex(t, c.fields["signature"]))
	}
	for _, name := range []string{"key-small-order-0", "key-small-order-y-p-plus-1", "r-small-order-0", "valid"} {
		if !std(name) {
			t.Errorf("ed25519.Verify refuses %s", name)
		}
	}
	for _, name := range []string{"s-plus-l", "s-top-bit", "r-mixed-order-1", "r-small-order-y-p-plus-1"} {
		if std(name) {
			t.Errorf("ed25519.Verify accepts %s", name)
		}
	}
}

// Arbitrary bytes and every vector cut and changed: no panic, and no
// changed entry accepted. Verify takes any lengths.
func TestNoPanics(t *testing.T) {
	x := uint64(0x5eed)
	next := func() uint64 {
		x += 0x9e3779b97f4a7c15
		z := x
		z = (z ^ z>>30) * 0xbf58476d1ce4e5b9
		z = (z ^ z>>27) * 0x94d049bb133111eb
		return z ^ z>>31
	}
	for n := 0; n < 400; n++ {
		b := make([]byte, n)
		for i := range b {
			b[i] = byte(next())
		}
		VerifyEntry(b)
		Verify(b[:min(n, 32)], b, b[min(n, 32):])
	}
	valid := map[string]bool{}
	vectors := records(t, "../../vectors/entries.txt")
	for _, r := range vectors {
		if r.fields["valid"] == "yes" {
			valid[r.fields["bytes"]] = true
		}
	}
	for _, r := range vectors {
		if !strings.HasPrefix(r.head, "entry ") {
			continue
		}
		bytes := unhex(t, r.fields["bytes"])
		for cut := range len(bytes) + 1 {
			VerifyEntry(bytes[:cut])
		}
		for range 200 {
			if len(bytes) == 0 {
				break
			}
			b := append([]byte(nil), bytes...)
			b[next()%uint64(len(b))] ^= 1 << (next() % 8)
			if next()%4 == 0 {
				b[min(108, len(b)-1)] = byte(next())
			}
			if _, err := VerifyEntry(b); err == nil && !valid[hex.EncodeToString(b)] {
				t.Fatalf("%s: accepted a changed entry %x", r.head, b)
			}
		}
	}
}

// FuzzVerifyEntry: go test -fuzz FuzzVerifyEntry. Without -fuzz it runs
// the vectors as seeds.
func FuzzVerifyEntry(f *testing.F) {
	for _, r := range records(f, "../../vectors/entries.txt") {
		if b := r.fields["bytes"]; b != "" {
			f.Add(unhex(f, b))
		}
	}
	f.Fuzz(func(t *testing.T, b []byte) {
		e, err := VerifyEntry(b)
		if err == nil && (len(b) != 173+len(e.Title) || e.Seq == 0) {
			t.Fatalf("accepted %x", b)
		}
	})
}

// TestCorpus writes VerifyEntry's verdict on each line (hex) of the file
// TERSENET_CORPUS to TERSENET_VERDICTS: crates/terse-cli/tests/
// sdk_agreement.rs compares it with the other implementations.
func TestCorpus(t *testing.T) {
	in, out := os.Getenv("TERSENET_CORPUS"), os.Getenv("TERSENET_VERDICTS")
	if in == "" {
		t.Skip("TERSENET_CORPUS not set: run by crates/terse-cli/tests/sdk_agreement.rs")
	}
	text, err := os.ReadFile(in)
	if err != nil {
		t.Fatal(err)
	}
	var verdicts strings.Builder
	for _, line := range strings.Fields(string(text)) {
		_, err := VerifyEntry(unhex(t, line))
		verdict := "valid"
		for name, rule := range rules {
			if err == rule {
				verdict = name
			}
		}
		if err != nil && verdict == "valid" {
			t.Fatalf("unknown error %v", err)
		}
		verdicts.WriteString(verdict + "\n")
	}
	if err := os.WriteFile(out, []byte(verdicts.String()), 0o644); err != nil {
		t.Fatal(err)
	}
}
